import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const DIR = '/workspace/probe/corpus/scalars-quoted';
const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
let ok = 0, err = 0;
const show = (s) => JSON.stringify(s);

for (const f of files) {
  const input = readFileSync(`${DIR}/${f}`, 'utf8');
  let out, rc = 0;
  try {
    out = execFileSync(EXE, ['--a', input], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) {
    rc = e.status ?? -1;
    out = (e.stderr || '').split('\n').filter((l) => /Error|error/.test(l)).slice(-1)[0] || '<no msg>';
  }
  if (rc === 0) ok++; else err++;
  if (process.env.VERBOSE) console.log(`${f} rc=${rc} in=${show(input)}\n     out=${show(out)}`);
}
console.log(`total=${files.length} rc0=${ok} rcNonZero=${err}`);

