cd /workspace/probe/corpus/scalars-quoted && node -e '
const fs=require("fs");
const files=fs.readdirSync(".").sort();
let nul=0,dash=0,empty=0; const seen=new Map(); let dup=0;
let expect=1;
for(const f of files){
  const b=fs.readFileSync(f);
  const s=b.toString("utf8");
  if(f!==String(expect).padStart(3,"0")+".txt"){console.log("GAP at",f);} expect++;
  if(b.includes(0)) {nul++;console.log("NUL",f);}
  if(s.startsWith("-") && !s.split("\n")[0].includes(" ")){dash++;console.log("DASH",f,JSON.stringify(s.slice(0,20)));}
  if(s.length===0){empty++;console.log("EMPTY",f);}
  if(seen.has(s)){dup++;console.log("DUP",f,"==",seen.get(s));} else seen.set(s,f);
}
console.log("files="+files.length,"nul="+nul,"badDash="+dash,"empty="+empty,"dups="+dup,"distinct="+seen.size);
const q=[...seen.keys()].filter(s=>/["\x27]/.test(s)).length;
console.log("cases containing a quote char:",q);
'
